const body = $input.first().json.body || {};
const rawText = (body.prompt_asli || '').trim();
const lower = rawText.toLowerCase();
const mode = body.mode || 'txt2img';
const inputImage = body.input_image || null;

let detectedStyle = 'Photorealistic';
let styleTags = 'photorealistic, ultra-detailed photography, natural lighting, 8k uhd, dslr, sharp focus';
let negativeExtra = 'anime, cartoon, 3d render, illustration, painting, drawing';

if (lower.includes('anime') || lower.includes('kartun') || lower.includes('manga') || lower.includes('ghibli')) {
  detectedStyle = 'Anime / Illustration';
  styleTags = 'anime style, studio ghibli style, vibrant colors, cinematic anime lighting, makoto shinkai style, highly detailed illustration';
  negativeExtra = 'photorealistic, 3d render, live action';
} else if (lower.includes('3d') || lower.includes('pixar') || lower.includes('disney') || lower.includes('render')) {
  detectedStyle = '3D Render';
  styleTags = '3d render, cute pixar style, disney animation style, octane render, unreal engine 5, ray tracing, volumetric lighting';
  negativeExtra = '2d, sketch, blurry, low poly';
} else if (lower.includes('lukisan') || lower.includes('cat air') || lower.includes('kanvas') || lower.includes('painting')) {
  detectedStyle = 'Digital Painting';
  styleTags = 'digital concept art, oil painting on canvas, artistic brushstrokes, dramatic lighting';
  negativeExtra = 'photo, camera, 3d';
} else if (lower.includes('cyberpunk') || lower.includes('neon') || lower.includes('futuristik') || lower.includes('robot')) {
  detectedStyle = 'Cyberpunk Sci-Fi';
  styleTags = 'cyberpunk aesthetic, neon lights, futuristic atmosphere, cinematic sci-fi lighting, hyper-detailed';
  negativeExtra = 'vintage, rustic';
}

const cleanText = rawText.replace(/\s+/g, ' ').trim();

return [{
  json: {
    chatId: body.chatId,
    prompt_asli: cleanText,
    mode: mode,
    input_image: inputImage,
    detected_style: detectedStyle,
    style_tags: styleTags,
    negative_extra: negativeExtra,
    start_time: body.timestamp_masuk || Date.now()
  }
}];

