parameters.jsCode:
const prep = $('2. NLP Preprocessing & Deteksi Gaya').first().json;
const rawResponse = $input.first().json.response || '{}';

let subjectEn = '';
let detailsEn = '';

try {
  const parsed = JSON.parse(rawResponse);
  subjectEn = (parsed.subject_en || parsed.subject || '').trim();
  detailsEn = (parsed.details_en || parsed.details || parsed.prompt || '').trim();
} catch (e) {
  subjectEn = rawResponse.replace(/[\{\}\"]/g, '').trim();
}

if (!subjectEn) {
  subjectEn = prep.prompt_asli;
}

const finalPrompt = `(${subjectEn}:1.3), ${detailsEn ? detailsEn + ', ' : ''}${prep.style_tags}, masterpiece, best quality, intricate details`;
const negativePrompt = `${prep.negative_extra}, lowres, bad anatomy, bad proportions, extra limbs, extra fingers, mutated hands, poorly drawn face, deformed, ugly, blurry, watermark, text, signature, cropped, out of frame`;

const sdEndpoint = (prep.mode === 'img2img' && prep.input_image)
  ? 'http://127.0.0.1:7860/sdapi/v1/img2img'
  : 'http://127.0.0.1:7860/sdapi/v1/txt2img';

const sdPayload = {
  prompt: finalPrompt,
  negative_prompt: negativePrompt,
  steps: 25,
  cfg_scale: 7,
  width: 512,
  height: 512,
  sampler_name: 'DPM++ 2M Karras',
  override_settings: {
    CLIP_stop_at_last_layers: 2
  }
};

if (prep.mode === 'img2img' && prep.input_image) {
  sdPayload.init_images = [prep.input_image];
  sdPayload.denoising_strength = 0.65;
  sdPayload.resize_mode = 1;
}

return [{
  json: {
    chatId: prep.chatId,
    prompt_asli: prep.prompt_asli,
    mode: prep.mode,
    detected_style: prep.detected_style,
    subject_en: subjectEn,
    final_prompt: finalPrompt,
    sd_endpoint: sdEndpoint,
    sd_payload: sdPayload,
    start_time: prep.start_time
  }
}];
